import csv, datetime, json, os
dataset = PARAMS['dataset']
key = PARAMS.get('key_column', 'customer_id')
as_of = datetime.date.fromisoformat(PARAMS.get('as_of', '2026-11-30'))
with open(os.path.join(INPUT_DIRS[0], dataset + '.csv'), newline='', encoding='utf-8-sig') as f:
    rows = list(csv.DictReader(f))
REQUIRED = ['customer_id', 'name', 'email', 'country']
STATUSES = {'active', 'inactive', 'prospect'}
def num(v):
    try: return float(v)
    except ValueError: return None
issues, seen = [], set()
for n, r in enumerate(rows, start=1):
    k = r.get(key, '')
    for col in REQUIRED:
        if not r.get(col, '').strip():
            issues.append([n, k, col, 'missing_required', ''])
    email = r.get('email', '').strip()
    if email and ('@' not in email or '.' not in email.split('@')[-1] or ' ' in email):
        issues.append([n, k, 'email', 'bad_email', email])
    try:
        d = datetime.date.fromisoformat(r.get('signup_date', ''))
        if d > as_of: issues.append([n, k, 'signup_date', 'bad_date', r['signup_date']])
    except ValueError:
        issues.append([n, k, 'signup_date', 'bad_date', r.get('signup_date', '')])
    cl = num(r.get('credit_limit', ''))
    if cl is None or cl < 0:
        issues.append([n, k, 'credit_limit', 'out_of_range', r.get('credit_limit', '')])
    dp = num(r.get('discount_pct', ''))
    if dp is None or not 0 <= dp <= 50:
        issues.append([n, k, 'discount_pct', 'out_of_range', r.get('discount_pct', '')])
    if r.get('status', '') not in STATUSES:
        issues.append([n, k, 'status', 'invalid_value', r.get('status', '')])
    if k and k in seen:
        issues.append([n, k, key, 'duplicate_key', k])
    seen.add(k)
with open(os.path.join(OUTPUT_DIR, f'dq_issues_{dataset}.csv'), 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f); w.writerow(['row', 'key', 'column', 'rule', 'value']); w.writerows(issues)
summary = {'dataset': dataset, 'rows': len(rows), 'issues': len(issues), 'rows_with_issues': len({i[0] for i in issues}),
           'by_rule': {}, 'passed': not issues}
for i in issues: summary['by_rule'][i[3]] = summary['by_rule'].get(i[3], 0) + 1
open(os.path.join(OUTPUT_DIR, f'dq_summary_{dataset}.json'), 'w').write(json.dumps(summary, indent=1))
print(json.dumps(summary))
